import { describe, expect, test } from "bun:test";
import { greet, add, slugify } from "./utils";

describe("utils", () => {
  test("greet returns greeting message", () => {
    expect(greet("Alice")).toBe("Hello, Alice!");
  });

  test("add returns sum of two numbers", () => {
    expect(add(2, 3)).toBe(5);
  });
});

describe("slugify", () => {
  describe("lowercase normalization (REQ-001)", () => {
    test("converts uppercase letters to lowercase", () => {
      expect(slugify("UPPERCASE")).toBe("uppercase");
    });

    test("converts mixed case to lowercase", () => {
      expect(slugify("Hello, World!")).toBe("hello-world");
    });
  });

  describe("space and underscore replacement (REQ-002)", () => {
    test("replaces spaces with hyphens", () => {
      expect(slugify("foo bar")).toBe("foo-bar");
    });

    test("replaces underscores with hyphens", () => {
      expect(slugify("foo_bar")).toBe("foo-bar");
    });

    test("replaces multiple underscores with single hyphen", () => {
      expect(slugify("Foo__Bar")).toBe("foo-bar");
    });

    test("replaces multiple spaces with single hyphen", () => {
      expect(slugify("foo   bar")).toBe("foo-bar");
    });
  });

  describe("invalid character removal (REQ-003)", () => {
    test("removes punctuation marks", () => {
      expect(slugify("Hello, World!")).toBe("hello-world");
    });

    test("removes special characters", () => {
      expect(slugify("foo@bar#baz$qux")).toBe("foobarbazqux");
    });

    test("keeps letters, numbers, and hyphens", () => {
      expect(slugify("test-123-abc")).toBe("test-123-abc");
    });
  });

  describe("hyphen collapsing (REQ-004)", () => {
    test("collapses multiple consecutive hyphens", () => {
      expect(slugify("a---b")).toBe("a-b");
    });

    test("collapses hyphens resulting from removed characters", () => {
      expect(slugify("Hello,,,World")).toBe("hello-world");
    });
  });

  describe("leading and trailing hyphen trimming (REQ-005)", () => {
    test("removes leading hyphens", () => {
      expect(slugify("---test")).toBe("test");
    });

    test("removes trailing hyphens", () => {
      expect(slugify("test---")).toBe("test");
    });

    test("removes both leading and trailing hyphens", () => {
      expect(slugify("---test---")).toBe("test");
    });

    test("trims hyphens from whitespace-padded input", () => {
      expect(slugify("  Foo__Bar  ")).toBe("foo-bar");
    });
  });

  describe("function signature and export (REQ-006)", () => {
    test("accepts string parameter and returns string", () => {
      const result = slugify("test");
      expect(typeof result).toBe("string");
    });
  });

  describe("edge case handling (REQ-007)", () => {
    test("handles empty string", () => {
      expect(slugify("")).toBe("");
    });

    test("handles string with only special characters", () => {
      expect(slugify("!!!")).toBe("");
    });

    test("handles string with only whitespace", () => {
      expect(slugify("   ")).toBe("");
    });

    test("handles string with only hyphens", () => {
      expect(slugify("---")).toBe("");
    });
  });

  describe("user story examples", () => {
    test("URL slug from title", () => {
      expect(slugify("Hello, World!")).toBe("hello-world");
      expect(slugify("Product: Super-Widget (2024)!")).toBe("product-super-widget-2024");
    });

    test("file name normalization", () => {
      expect(slugify("User Report: Jan 2024")).toBe("user-report-jan-2024");
      expect(slugify("data___export___final")).toBe("data-export-final");
    });

    test("database identifiers", () => {
      expect(slugify("Electronics & Gadgets")).toBe("electronics-gadgets");
    });
  });
});

